### Result
{"size":193,"seen":193,"linens":32,"linensClosed":[]}
### Ran Playwright code
```js
await (async (page) => { await page.locator('input[placeholder="Filter by name..."]').fill(''); await page.waitForTimeout(2000); return await page.evaluate(async () => { const g=document.querySelector('vaadin-grid'); const out=new Map(); for(let i=0;i<g.size;i+=3){ g.scrollToIndex(i); await new Promise(r=>setTimeout(r,60)); for(const r of g.shadowRoot.querySelectorAll('tbody tr')){ const cells=[...r.querySelectorAll('td')].map(td=>(td.querySelector('slot')?.assignedNodes()[0]?.innerText||'').trim()); if(cells[0]) out.set(cells[2], cells.join('|')); } } const v=[...out.values()]; return {size:g.size, seen:v.length, linens:v.filter(x=>/Linens/.test(x)).length, linensClosed:v.filter(x=>/Linens/.test(x)&&/Closed/.test(x))}; }); })(page);
```

